/**
 * @method
 * @name scwin.yearAu
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.yearAu = function () {
    /* sdd-asis-lifecycle:begin fn_yearAu — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    document.$c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil30100/jldfil30100.xml');
    /* sdd-asis-lifecycle:end */
};


