/**
 * @method
 * @name scwin.viewManualKeyWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param submitManualClssId
 * @returns
 * @hidden N
*/
scwin.viewManualKeyWord = async function (submitManualClssId) {
    /* sdd-asis-lifecycle:begin fn_ViewManualKeyWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const viewManulURL = '/jldfil35400/jldfil35400.xml';
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(viewManulURL), { id: "manualWin", scrollbars: true, resizable: false, width: "1000", height: "650", type: "pageFramePopup" }, { method: "searchSubmitManual", submitManualClssId: submitManualClssId });
    /* sdd-asis-lifecycle:end */
};
